(async () => {
  const mark = (key, value) => document.body.setAttribute(key, String(value));
  mark('data-bas-teardown-clean', 'false');
  mark('data-bas-teardown-leaked', 'unknown');
  mark('data-bas-teardown-reason', 'pending');
  let baselineIds;
  try {
    const raw = sessionStorage.getItem('__bas_baseline_sessions');
    baselineIds = raw === null ? null : JSON.parse(raw);
  } catch { baselineIds = null; }
  if (!Array.isArray(baselineIds) || baselineIds.some((id) => typeof id !== 'string' || !id)) {
    mark('data-bas-teardown-reason', 'baseline-missing');
    throw new Error('teardown refused: no valid session baseline');
  }
  const baseline = new Set(baselineIds);
  const listRows = async () => {
    try {
      const response = await fetch('/vrooli.web_console.v1.sessions.SessionsService/List', {
        method: 'POST', headers: { 'Content-Type': 'application/json' }, body: '{}', cache: 'no-store',
      });
      if (!response.ok) throw new Error('HTTP ' + response.status);
      const body = await response.json();
      const rows = Array.isArray(body) ? body : body && typeof body === 'object' && !body.error ? (body.sessions ?? []) : null;
      if (!Array.isArray(rows) || rows.some((row) => !row || typeof row.id !== 'string' || !row.id) || new Set(rows.map((row) => row.id)).size !== rows.length) {
        throw new Error('invalid session list');
      }
      return rows;
    } catch (error) {
      mark('data-bas-teardown-reason', 'inventory-unavailable');
      throw new Error('teardown session inventory unavailable: ' + String(error));
    }
  };
  const rows = await listRows();
  // Baseline difference is not ownership: an operator may open a session while
  // the case runs. The routed SQL lease supplies provenance for its own rows.
  const capturedId = localStorage.getItem('bas.terminalSmoke.sessionId') || '';
  const captured = rows.find((row) => row.id === capturedId && !baseline.has(row.id));
  if (captured && captured.owner !== 'vrooli-test-lease') {
    mark('data-bas-teardown-reason', 'ownership-unproven');
    throw new Error('teardown refused: captured session lease ownership is unproven');
  }
  const mine = rows.filter((row) => !baseline.has(row.id) && row.owner === 'vrooli-test-lease').map((row) => row.id);
  if (mine.length > 4) {
    mark('data-bas-teardown-reason', 'refused-too-many:' + mine.length);
    throw new Error('teardown refused: lease-owned session count exceeds the safety cap');
  }
  const failures = [];
  for (const id of mine) {
    try {
      const response = await fetch('/vrooli.web_console.v1.sessions.SessionsService/Delete', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json', 'X-Idempotency-Key': 'delete:' + id },
        body: JSON.stringify({ id, confirmation: 'DELETE:' + id }),
      });
      if (!response.ok) failures.push(response.status);
    } catch { failures.push('network'); }
  }
  // Retain exact IDs through the final read. Lost provenance must not hide a
  // surviving process after a partial delete, and a failed read is not absence.
  const deadline = Date.now() + 10000;
  let remaining = await listRows();
  let leaked = mine.filter((id) => remaining.some((row) => row.id === id));
  while (leaked.length && Date.now() < deadline) {
    await new Promise((resolve) => setTimeout(resolve, 250));
    remaining = await listRows();
    leaked = mine.filter((id) => remaining.some((row) => row.id === id));
  }
  mark('data-bas-teardown-deleted', mine.length - leaked.length);
  mark('data-bas-teardown-delete-failures', failures.length);
  mark('data-bas-teardown-delete-statuses', failures.join(','));
  mark('data-bas-teardown-leaked', leaked.length);
  mark('data-bas-teardown-reason', leaked.length ? 'leaked' : 'ok');
  mark('data-bas-teardown-clean', leaked.length === 0 ? 'true' : 'false');
  if (leaked.length) throw new Error('case leaked ' + leaked.length + ' lease-owned terminal session(s)');
})()
